import itertools, math

def girth_circulant(n, S):
    """Compute girth of circulant graph with connection set S"""
    adj = [[] for _ in range(n)]
    for i in range(n):
        for s in S:
            j = (i + s) % n
            if j > i:
                adj[i].append(j)
                adj[j].append(i)

    edges = []
    for i in range(n):
        for j in adj[i]:
            if i < j:
                edges.append((i, j))

    return compute_girth(edges, n)

